 for(int i=0;i<3000;++i){large.messages<<LogicalMessage{"unknown","Controllo "+QString::number(i),"Check "+QString::number(i),true};}timer.restart();auto manyWarnings=w.remainingChecks(large);check("Thousands of warnings keep summary bounded",manyWarnings.size()<5000&&manyWarnings.contains("2992")&&timer.elapsed()<1500);
